xquery.xq-expression:

declare variable $posts as node() external;

let $positive := count($posts//item[sentiment = "positive"])
let $negative := count($posts//item[sentiment = "negative"])
let $neutral := count($posts//item[sentiment = "neutral"])
let $total := count($posts//item)

return
<sentiment_analysis>
    <total_posts>{$total}</total_posts>
    <positive_posts>{$positive}</positive_posts>
    <negative_posts>{$negative}</negative_posts>
    <neutral_posts>{$neutral}</neutral_posts>
    <positive_percentage>{round($positive div $total * 100)}</positive_percentage>
    <negative_percentage>{round($negative div $total * 100)}</negative_percentage>
    <neutral_percentage>{round($neutral div $total * 100)}</neutral_percentage>
</sentiment_analysis>


declare variable $posts as node() external;

let $totalLikes := sum($posts//item/likes)
let $totalRetweets := sum($posts//item/retweets)
let $avgLikes := round($totalLikes div count($posts//item))
let $avgRetweets := round($totalRetweets div count($posts//item))

return
<engagement_metrics>
    <total_likes>{$totalLikes}</total_likes>
    <total_retweets>{$totalRetweets}</total_retweets>
    <average_likes>{$avgLikes}</average_likes>
    <average_retweets>{$avgRetweets}</average_retweets>
</engagement_metrics>
